def migrate_legacy_documents(apps, schema_editor):
    """Reprend les 3 pièces historiques sans supprimer les anciens champs."""
    Session = apps.get_model('examens', 'ExamSession')
    Required = apps.get_model('examens', 'RequiredDocument')
    Candidate = apps.get_model('examens', 'Candidate')
    CandidateDocument = apps.get_model('examens', 'CandidateDocument')

    for session in Session.objects.all():
        for code, name, required, order, _ in LEGACY_DOCUMENTS:
            Required.objects.get_or_create(
                session=session, code=code,
                defaults={'name': name, 'is_required': required, 'order': order},
            )

    for candidate in Candidate.objects.all():
        for code, name, required, order, field in LEGACY_DOCUMENTS:
            value = getattr(candidate, field, None)
            if not value:
                continue
            requirement = Required.objects.filter(
                session_id=candidate.session_id, code=code
            ).first()
            CandidateDocument.objects.get_or_create(
                candidate=candidate, required_document=requirement,
                defaults={
                    'file': value.name,
                    'legacy_label': name if requirement is None else '',
                    'status': 'recu',
                    'deposited_at': candidate.created_at,
                },
            )


